/* ──────────────────────────────────────────────────
   ゆめはん専用：サムネイルスライド シームレス＆インタラクティブ化
   ────────────────────────────────────────────────── */
.slide-thumbnail1 .img {
    animation: none !important;
    will-change: transform;
    display: flex;
}
.slide-thumbnail1 .img.ltr {
    transform: translateX(-50%);
}
/* 画像の間に隙間ができないようにする（超重要） */
.slide-thumbnail1 .img > div {
    flex-shrink: 0;
}
.slide-thumbnail1 .img img {
    display: block;
    padding: 5px;
    box-sizing: border-box;
}


/* ──────────────────────────────────────────────────
   ゆめはん専用：スマホギャラリースワイプ補正
   ────────────────────────────────────────────────── */
.slide-thumbnail1 {
    touch-action: pan-y;
    user-select: none;
    -webkit-user-select: none;
}
.slide-thumbnail1 .img,
.slide-thumbnail1 .img a,
.slide-thumbnail1 .img img {
    user-select: none;
    -webkit-user-select: none;
    -webkit-user-drag: none;
}

/* ─────── ゆめはん専用 営業日カレンダー ─────── */
.yumekan-calendar-wrapper {
    margin: 40px auto;
    text-align: center;
}
.calendar-main-title {
    font-size: 17px;
    font-weight: bold;
    color: #d63384;
    margin-bottom: 14px;
    font-family: 'Sawarabi Mincho', 'Noto Sans JP', sans-serif;
    letter-spacing: 0.5px;
}

.yumekan-calendar-mini {
    max-width: 300px;
    width: 88vw;
    margin: 0 auto;
    background: #fff;
    border-radius: 14px;
    overflow: hidden;
    box-shadow: none !important;        /* ← 影を完全削除 */
    font-family: 'Sawarabi Mincho', 'Noto Sans JP', sans-serif;
    font-size: 13px;
    user-select: none;
    display: inline-block;
    border: 1px solid #ffe0e9;           /* 淡い枠線は残して優しさキープ */
}

.calendar-header {
    background: #d63384;
    color: #fff;
    padding: 5px 8px !important;     /* 縦幅半分 */
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 15px;
    font-weight: 600;
}

.nav-btn {
    background: rgba(255,255,255,0.25);
    border: none;
    width: 30px; height: 30px;
    border-radius: 50%;
    color: #fff;
    font-size: 16px;
    cursor: pointer;
}
.nav-btn:hover { background: rgba(255,255,255,0.4); }

.today-status {
    text-align: center;
    padding: 5px 6px !important;     /* 縦幅半分 */
    font-size: 13.5px;
    font-weight: bold;
    background: #fff0f6;
    color: #d63384;
    border-bottom: 1px solid #ffe0e9;
    line-height: 1.3;
}

.weekdays {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    background: #fff0f6;
    font-weight: bold;
    color: #d63384;
    font-size: 11.5px;
}
.weekdays span { text-align: center; padding: 7px 0; }

.days-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 1px;
    background: #ddd;
}
.days-grid div {
    background: #fff;
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12.5px;
}
.days-grid .day:hover { background: #fff8fa !important; }

/* 休日（土日祝） */
.holiday, .sunday, .saturday { 
    background: #ffebee !important; 
    color: #e91e63 !important; 
    font-weight: bold;
}
.other-month { color: #ddd; background: #fafafa !important; }

/* 今日を可愛く目立たせる「左上にピンクドット」影なし版 */
.days-grid .today {
    position: relative;
    font-weight: bold !important;
    z-index: 1;
}

/* 左上にシンプルな丸いピンクドット（影なし） */
.days-grid .today::before {
    content: "";
    position: absolute;
    top: 4px;
    left: 4px;
    width: 10px;
    height: 10px;
    background: #333ed6;
    border-radius: 50%;
    border: 2.5px solid #fff;      /* 白フチでくっきり */
    pointer-events: none;
    z-index: 2;
}

/* 数字がドットに重ならないよう微調整 */
.days-grid .today {
    padding-left: 4px;
    padding-top: 4px;
}

/* ドットの位置を微調整（数字が隠れないように） */
.days-grid .today {
    padding-left: 2px;
    padding-top: 2px;
}

/* ─────── ゆめはん専用 フローティング検索 v2（グレー＆超透明・列揃え）─────── */
.yumekan-floating-search-v2 {
    --search-pulse-count: 3;
    --search-pulse-color-rgb: 128, 255, 128;
    position: fixed;
    right: 36px;              /* ← ハンバーガーメニューと完全に列を合わせる値（必要に応じて±2pxで微調整） */
    bottom: 24px;
    z-index: 9998;
    display: flex;
    align-items: center;
    font-family: 'Sawarabi Mincho', 'Noto Sans JP', sans-serif;
}

.yumekan-floating-search-v2 .search-toggle {
    position: relative;
    overflow: visible;
    width: 56px;
    height: 56px;
    background: rgba(255, 255, 255, 0.75);   /* 超透明 */
    backdrop-filter: blur(12px);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: #666;              /* グレー系 */
    border: 1.8px solid rgba(180, 180, 180, 0.4);
    box-shadow: none;         /* 影完全削除 */
    transition: all 0.35s ease;
}

.yumekan-floating-search-v2 .search-toggle:hover {
    background: rgba(255, 255, 255, 0.95);
    transform: scale(1.07);
}

.yumekan-floating-search-v2 .search-toggle.search-pulse {
    animation: searchButtonSoftPulse 1.8s ease-out var(--search-pulse-count);
}

.yumekan-floating-search-v2 .search-toggle.search-pulse::after {
    content: "";
    position: absolute;
    inset: -8px;
    border-radius: 50%;
    border: 2px solid rgba(var(--search-pulse-color-rgb), 0.55);
    pointer-events: none;
    animation: searchButtonPulseRing 1.8s ease-out var(--search-pulse-count);
}

@keyframes searchButtonSoftPulse {
    0%, 100% {
        background: rgba(255, 255, 255, 0.75);
        box-shadow: none;
        transform: scale(1);
    }
    32% {
        background: rgba(255, 255, 255, 0.98);
        box-shadow: 0 0 20px rgba(var(--search-pulse-color-rgb), 0.34);
        transform: scale(1.06);
    }
}

@keyframes searchButtonPulseRing {
    0% {
        opacity: 0;
        transform: scale(0.9);
    }
    18% {
        opacity: 1;
    }
    100% {
        opacity: 0;
        transform: scale(1.55);
    }
}

.yumekan-floating-search-v2 .search-input {
    height: 56px;
    padding: 0 24px;
    border: none;
    border-radius: 28px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(12px);
    font-size: 15px;
    color: #444;
    outline: none;
    box-shadow: none;         /* 影なし */
    margin-right: -68px;
    width: 0;
    opacity: 0;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    border: 1.8px solid rgba(180, 180, 180, 0.3);
}

.yumekan-floating-search-v2.active .search-input {
    width: 280px;
    opacity: 1;
    padding: 0 24px;
}

/* スマホ調整 */
@media (max-width: 480px) {
    .yumekan-floating-search-v2 { right: 24px; bottom: 18px; }
    .yumekan-floating-search-v2.active .search-input { width: 210px; }
    .yumekan-floating-search-v2 .search-toggle { width: 50px; height: 50px; }
}

